1	"use client";
2	
3	import * as React from "react";
4	import { ChevronUp, ChevronDown, ChevronsUpDown } from "lucide-react";
5	
6	export interface Column<T> {
7	  key: string;
8	  header: string;
9	  align?: "left" | "right";
10	  sortable?: boolean;
11	  /** Custom cell content; defaults to String(row[key]). */
12	  render?: (row: T) => React.ReactNode;
13	  /** Value used for sorting; defaults to render-less row[key]. */
14	  sortValue?: (row: T) => string | number;
15	}
16	
17	interface SortState {
18	  key: string;
19	  dir: "asc" | "desc";
20	}
21	
22	/**
23	 * Accessible data table: real `<table>` with a `<caption>`, `<thead>`, and
24	 * `<th scope="col">`. Sortable columns are keyboard-operable `<button>`s; the
25	 * `<th>`'s `aria-sort` reflects state and a live region announces each change.
26	 */
27	export function DataTable<T>({
28	  caption,
29	  columns,
30	  rows,
31	  getRowKey,
32	  captionVisible = false,
33	  emptyText,
34	}: {
35	  caption: string;
36	  columns: Column<T>[];
37	  rows: T[];
38	  getRowKey: (row: T, index: number) => string;
39	  captionVisible?: boolean;
40	  emptyText?: string;
41	}) {
42	  const [sort, setSort] = React.useState<SortState | null>(null);
43	  const [announce, setAnnounce] = React.useState("");
44	
45	  const sorted = React.useMemo(() => {
46	    if (!sort) return rows;
47	    const col = columns.find((c) => c.key === sort.key);
48	    if (!col) return rows;
49	    const value = (row: T): string | number =>
50	      col.sortValue
51	        ? col.sortValue(row)
52	        : ((row as Record<string, unknown>)[col.key] as string | number);
53	    const factor = sort.dir === "asc" ? 1 : -1;
54	    return [...rows].sort((a, b) => {
55	      const av = value(a);
56	      const bv = value(b);
57	      if (av < bv) return -1 * factor;
58	      if (av > bv) return 1 * factor;
59	      return 0;
60	    });
61	  }, [rows, sort, columns]);
62	
63	  function toggleSort(col: Column<T>) {
64	    setSort((prev) => {
65	      const dir: "asc" | "desc" =
66	        prev?.key === col.key && prev.dir === "asc" ? "desc" : "asc";
67	      setAnnounce(
68	        `Sorted by ${col.header}, ${dir === "asc" ? "ascending" : "descending"}`,
69	      );
70	      return { key: col.key, dir };
71	    });
72	  }
73	
74	  return (
75	    <div className="overflow-x-auto rounded-card border border-border">
76	      <table className="w-full border-collapse text-left text-base">
77	        <caption
78	          className={captionVisible ? "px-4 py-3 text-left text-h3" : "sr-only"}
79	        >
80	          {caption}
81	        </caption>
82	        <thead>
83	          <tr className="border-b border-border bg-surface-sunk">
84	            {columns.map((col) => {
85	              const active = sort?.key === col.key;
86	              const ariaSort = active
87	                ? sort.dir === "asc"
88	                  ? "ascending"
89	                  : "descending"
90	                : "none";
91	              return (
92	                <th
93	                  key={col.key}
94	                  scope="col"
95	                  aria-sort={col.sortable ? ariaSort : undefined}
96	                  className={[
97	                    "px-4 py-3 text-sm font-bold text-ink-soft",
98	                    col.align === "right" ? "text-right" : "text-left",
99	                  ].join(" ")}
100	                >
101	                  {col.sortable ? (
102	                    <button
103	                      type="button"
104	                      onClick={() => toggleSort(col)}
105	                      className={[
106	                        "inline-flex items-center gap-1 rounded-sm font-bold text-ink-soft hover:text-ink",
107	                        col.align === "right" ? "flex-row-reverse" : "",
108	                      ].join(" ")}
109	                    >
110	                      {col.header}
111	                      {active ? (
112	                        sort.dir === "asc" ? (
113	                          <ChevronUp size={15} strokeWidth={2.5} aria-hidden="true" />
114	                        ) : (
115	                          <ChevronDown size={15} strokeWidth={2.5} aria-hidden="true" />
116	                        )
117	                      ) : (
118	                        <ChevronsUpDown
119	                          size={15}
120	                          strokeWidth={2}
121	                          aria-hidden="true"
122	                          className="text-ink-faint"
123	                        />
124	                      )}
125	                    </button>
126	                  ) : (
127	                    col.header
128	                  )}
129	                </th>
130	              );
131	            })}
132	          </tr>
133	        </thead>
134	        <tbody>
135	          {sorted.length === 0 ? (
136	            <tr>
137	              <td
138	                colSpan={columns.length}
139	                className="px-4 py-6 text-center text-base text-ink-soft"
140	              >
141	                {emptyText ?? "Nothing to show yet."}
142	              </td>
143	            </tr>
144	          ) : (
145	            sorted.map((row, i) => (
146	              <tr
147	                key={getRowKey(row, i)}
148	                className="border-b border-border last:border-0"
149	              >
150	                {columns.map((col) => (
151	                  <td
152	                    key={col.key}
153	                    className={[
154	                      "px-4 py-3 text-ink",
155	                      col.align === "right" ? "text-right" : "text-left",
156	                    ].join(" ")}
157	                  >
158	                    {col.render
159	                      ? col.render(row)
160	                      : String((row as Record<string, unknown>)[col.key] ?? "")}
161	                  </td>
162	                ))}
163	              </tr>
164	            ))
165	          )}
166	        </tbody>
167	      </table>
168	      <div className="sr-only" aria-live="polite">
169	        {announce}
170	      </div>
171	    </div>
172	  );
173	}
