21	  --ink-faint:     #948B81;  /* tertiary / placeholder                 */
22	
23	  --primary:       #136F63;  /* calm teal — trust; primary buttons     */
24	  --primary-dark:  #0E5249;  /* hover / active                        */
25	  --primary-tint:  #E4EFEC;  /* teal wash — selected chips, fills      */
26	
27	  --accent:        #E08A3C;  /* warm amber — tips, gentle highlights   */
28	  --accent-dark:   #C4732C;  /* amber hover / active                   */
29	  --accent-tint:   #FBEBD9;  /* amber wash                            */
30	
31	  --success:       #2E7D5B;  /* available / positive (pair w/ text)    */
32	  --success-tint:  #E3F0EA;
33	  --alert:         #B23A2E;  /* errors / safety (pair w/ text)         */
