39	
40	  /* ---- Type families --------------------------------------------- */
41	  --font-display: 'Lora', Georgia, 'Times New Roman', serif;  /* warm humanist serif — headings */
42	  --font-body:    'Nunito Sans', system-ui, -apple-system, sans-serif;
43	
44	  /* ---- Type scale (px). Body floor = 18px ------------------------ */
45	  --text-xs:   14px;   /* meta / fine print — use sparingly          */
46	  --text-sm:   16px;   /* labels, secondary                         */
47	  --text-base: 18px;   /* BODY MINIMUM                              */
48	  --text-lg:   20px;   /* large body / lead                         */
49	  --text-h3:   24px;
50	  --text-h2:   30px;
51	  --text-h1:   38px;
52	  --text-display: 46px;
53	
54	  --leading-tight: 1.2;
55	  --leading-snug:  1.35;
56	  --leading-body:  1.6;   /* generous body line-height               */
57	
58	  --weight-regular: 400;
59	  --weight-semibold: 600;
60	  --weight-bold: 700;
61	  --weight-extrabold: 800;
62	
63	  /* ---- Spacing — 8px grid ---------------------------------------- */
64	  --space-1: 4px;
65	  --space-2: 8px;
66	  --space-3: 12px;
67	  --space-4: 16px;
68	  --space-5: 24px;
69	  --space-6: 32px;
70	  --space-7: 48px;
71	  --space-8: 64px;
72	  --space-9: 96px;
73	
74	  /* ---- Radii ----------------------------------------------------- */
75	  --radius-sm:   8px;
76	  --radius-btn:  12px;   /* buttons                                  */
77	  --radius-card: 16px;   /* cards, sheets                            */
78	  --radius-lg:   24px;   /* large surfaces / hero                    */
79	  --radius-pill: 999px;  /* chips, toggles, avatars                  */
80	
81	  /* ---- Shadows — soft, low, warm --------------------------------- */
82	  --shadow-xs: 0 1px 2px rgba(42, 38, 34, 0.05);
83	  --shadow-sm: 0 2px 8px rgba(42, 38, 34, 0.06);
84	  --shadow-md: 0 6px 20px rgba(42, 38, 34, 0.08);
85	  --shadow-lg: 0 14px 40px rgba(42, 38, 34, 0.12);
86	
87	  /* ---- Focus ring — never removed -------------------------------- */
88	  --focus-ring: 0 0 0 3px var(--focus);
89	  --focus-ring-offset: 0 0 0 2px var(--surface), 0 0 0 5px var(--focus);
90	
91	  /* ---- Min interactive target ------------------------------------ */
92	  --tap-min: 48px;
93	
94	  /* ---- Motion (gentle; respect reduced-motion) ------------------- */
95	  --ease: cubic-bezier(0.33, 0.1, 0.25, 1);
96	  --dur-fast: 120ms;
97	  --dur: 200ms;
98	  --dur-slow: 320ms;
99	}
