116	
117	h1, h2, h3, h4 {
118	  font-family: var(--font-display);
119	  color: var(--ink);
120	  line-height: var(--leading-tight);
121	  text-wrap: balance;
122	  margin: 0;
123	}
124	h1 { font-size: var(--text-h1); font-weight: 700; letter-spacing: -0.01em; }
125	h2 { font-size: var(--text-h2); font-weight: 700; letter-spacing: -0.01em; }
126	h3 { font-size: var(--text-h3); font-weight: var(--weight-bold); }
127	
128	p  { margin: 0; text-wrap: pretty; }
129	.lead { font-size: var(--text-lg); color: var(--ink-soft); line-height: var(--leading-body); }
130	.meta { font-size: var(--text-sm); color: var(--ink-soft); }
131	
132	a { color: var(--primary); text-underline-offset: 3px; }
133	a:hover { color: var(--primary-dark); }
134	
135	/* ---- Universal visible focus — the single most important rule ----- */
136	:where(a, button, input, select, textarea, [tabindex], [role="button"], [role="tab"]):focus-visible {
137	  outline: none;
138	  box-shadow: var(--focus-ring);
139	  border-radius: var(--radius-sm);
140	}
141	
