67	          <ul className="flex flex-col gap-4">
68	            {decidedWithAudio.map(({ provider, audioUrl }) => (
69	              <ProviderApprovalCard
70	                key={provider.id}
71	                provider={provider}
72	                audioUrl={audioUrl}
73	              />
74	            ))}
75	          </ul>
